<template>
<view class="page-body admin">
 <view class="admin-head"><view class="flex-between"><view class="flex-row gap"><SchoolLogo class="seal"/><view><text class="head-title">失物招领管理平台</text><text class="head-sub">校园失物招领 · 课程项目</text></view></view><view @tap="signOut"><AppIcon name="logout" :size="33"/></view></view></view>
 <view class="page-pad dashboard">
   <view class="dash-title">数据看板</view><view class="dash-sub">{{today}}　运营数据概览</view>
   <view class="metric-grid"><view class="metric"><AppIcon name="search" :size="38"/><text>今日丢失登记</text><text>{{data.todayLost}}</text></view><view class="metric"><AppIcon name="notice" :size="38"/><text>今日招领发布</text><text>{{data.todayFound}}</text></view><view class="metric"><AppIcon name="check" :size="38"/><text>今日成功归还</text><text>{{data.todayReturned}}</text></view><view class="metric"><AppIcon name="clock" :size="38"/><text>待审核处理</text><text>{{data.pending}}</text></view></view>
   <view class="panel"><view class="section-title">近七日数据趋势</view><view class="legend"><view><text class="legend-dot blue"></text>丢失</view><view><text class="legend-dot green"></text>招领</view><view><text class="legend-dot orange"></text>归还</view></view>
     <view class="bar-chart"><view v-for="(day,i) in data.trends" :key="i" class="day"><view class="bar-area"><view class="bar b-blue" :style="{height:barHeight(day.lost)+'%'}"></view><view class="bar b-green" :style="{height:barHeight(day.found)+'%'}"></view><view class="bar b-orange" :style="{height:barHeight(day.returned)+'%'}"></view></view><text>{{day.date.slice(3)}}</text></view></view>
     <text class="chart-tip">数量基于已同步的记录动态统计，新增与状态变更会更新此图。</text>
   </view>
   <view class="panel"><view class="section-title">失物高发地点</view><view v-for="(loc,i) in data.locations.slice(0,6)" :key="loc.name" class="rank"><text class="rank-no">{{i+1}}</text><text class="rank-label">{{loc.name}}</text><view class="rank-track"><view :style="{width:rankWidth(loc.value)+'%'}"></view></view><text class="rank-value">{{loc.value}}</text></view><view v-if="!data.locations.length" class="no-data">暂无地点数据</view></view>
   <view class="panel"><view class="section-title">物品分类分布</view><view v-for="cat in data.categories" :key="cat.name" class="category-row"><text>{{cat.name}}</text><view class="rank-track"><view :style="{width:(cat.value / Math.max(1,data.total)*100)+'%'}"></view></view><text>{{cat.value}}件</text></view></view>
   <view class="panel"><view class="section-head"><text class="section-title">待处理记录</text><text class="all" @tap="openRecords">查看全部 ›</text></view><view v-for="p in recent" :key="p.id" class="recent-row" @tap="openRecords"><text>{{p.title}}</text><text>{{p.location}}</text><text class="pill pill-wait">{{STATUS[p.status]}}</text></view><view v-if="!recent.length" class="no-data">没有待审核信息</view></view>
   <view class="warning">统计来自平台记录，尚未接入学校统一身份认证。</view>
 </view>
 <AdminNav active="dashboard"/>
</view>
</template>
<script setup>
import {ref,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import SchoolLogo from '../../../components/SchoolLogo.vue';import AppIcon from '../../../components/AppIcon.vue';import AdminNav from '../../../components/AdminNav.vue';import {stats,posts,session,logout,STATUS,dateOnly,requireRole,refreshCloud} from '../../../utils/store.js'
const data=ref({todayLost:0,todayFound:0,todayReturned:0,pending:0,total:0,trends:[],locations:[],categories:[]}),all=ref([]),today=dateOnly()
onShow(async()=>{if(!requireRole('admin'))return;try{await refreshCloud();data.value=stats();all.value=posts()}catch(e){uni.showToast({title:e.message||'数据加载失败',icon:'none'})}})
const recent=computed(()=>all.value.filter(p=>p.status==='pending').slice(0,5))
function barHeight(n){const arr=data.value.trends||[];const max=Math.max(1,...arr.flatMap(x=>[x.lost,x.found,x.returned]));return Math.max(2,(n/max)*88)}
function rankWidth(n){return n/Math.max(1,...data.value.locations.map(x=>x.value))*100}
function openRecords(){uni.redirectTo({url:'/pages/admin/records/records'})}
function signOut(){uni.showModal({title:'退出管理平台',content:'是否退出当前管理员账号？',success:async r=>{if(r.confirm){await logout();uni.reLaunch({url:'/pages/login/login'})}}})}
</script>
<style scoped>
.admin-head{background:#002554;color:white;padding:22rpx 26rpx}.gap{gap:13rpx}.seal{width:66rpx;height:66rpx}.head-title{color:white;font-size:29rpx;font-weight:750;display:block}.head-sub{color:#bbcddf;font-size:20rpx;display:block;margin-top:5rpx}.dashboard{padding-top:26rpx}.dash-title{font-size:41rpx;font-weight:800;color:#002554}.dash-sub{font-size:22rpx;color:#8090a2;margin-top:10rpx;margin-bottom:24rpx}.metric-grid{display:grid;grid-template-columns:1fr 1fr;gap:15rpx}.metric{background:#fff;border:1rpx solid #e5ebf0;padding:23rpx 22rpx;display:flex;flex-direction:column;gap:8rpx}.metric text:nth-child(2){font-size:24rpx;color:#75889c}.metric text:nth-child(3){font-size:49rpx;font-weight:800;color:#002554}.panel{margin-top:17rpx;background:#fff;padding:27rpx 22rpx;border:1rpx solid #e6ebef}.legend{display:flex;justify-content:flex-end;gap:23rpx;font-size:21rpx;color:#6f8192}.legend view{display:flex;align-items:center;gap:7rpx}.legend-dot{width:12rpx;height:12rpx;border-radius:50%}.blue{background:#2870ba}.green{background:#177f62}.orange{background:#cb864a}.bar-chart{height:260rpx;margin-top:20rpx;border-bottom:1rpx solid #e0e8ec;display:flex;align-items:stretch;justify-content:space-between}.day{flex:1;display:flex;flex-direction:column;justify-content:end;align-items:center;gap:9rpx}.day>text{font-size:20rpx;color:#8595a2;margin-bottom:-26rpx}.bar-area{height:210rpx;display:flex;align-items:end;justify-content:center;gap:3rpx;width:100%}.bar{width:14rpx;min-height:3rpx}.b-blue{background:#3477c3}.b-green{background:#3a9e78}.b-orange{background:#e3a461}.chart-tip{display:block;margin-top:43rpx;color:#8998a5;font-size:20rpx;line-height:1.6}.rank,.category-row{display:flex;align-items:center;gap:13rpx;margin-top:21rpx}.rank-no{font-size:22rpx;color:#8598a5;width:23rpx}.rank-label{font-size:23rpx;width:175rpx;color:#405875}.rank-track{height:18rpx;flex:1;background:#edf2f5;overflow:hidden}.rank-track view{height:100%;background:#5f9fd4}.rank-value{font-size:22rpx;min-width:27rpx;color:#536b7f}.category-row text:first-child{font-size:23rpx;min-width:135rpx;color:#456078}.category-row text:last-child{font-size:21rpx;color:#627486}.all{color:#3c6d97;font-size:22rpx}.recent-row{display:flex;align-items:center;gap:7rpx;font-size:23rpx;padding:19rpx 0;border-bottom:1rpx solid #edf0f4}.recent-row text:first-child{flex:1;color:#30465d}.recent-row text:nth-child(2){font-size:20rpx;color:#899aaa}.warning{margin-top:25rpx;color:#a97b3d;font-size:21rpx;line-height:1.5}
</style>
